-- TOC entry 607 (class 1255 OID 25725)
-- Name: get_depart_ancestors(integer); Type: FUNCTION; Schema: users; Owner: postgres
--

CREATE FUNCTION users.get_depart_ancestors(depart_id integer) RETURNS TABLE(id integer, depart_code character varying, depart_name character varying, depart_type_id integer, depart_type_name character varying, depart_type_level integer, parent_id integer, level integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH RECURSIVE ancestors AS (
        -- Base case: Start from given department
        SELECT 
            d.id,
            d.depart_code,
            d.depart_name,
            d.depart_type_id,
            dt.depart_type_name,
            dt.depart_type_level,
            d.parent_id,
            0 as level
        FROM users.tb_departs d
        INNER JOIN users.tb_depart_types dt ON dt.id = d.depart_type_id
        WHERE d.id = depart_id
        
        UNION ALL
        
        -- Recursive case: Get parent
        SELECT 
            d.id,
            d.depart_code,
            d.depart_name,
            d.depart_type_id,
            dt.depart_type_name,
            dt.depart_type_level,
            d.parent_id,
            a.level + 1
        FROM users.tb_departs d
        INNER JOIN users.tb_depart_types dt ON dt.id = d.depart_type_id
        INNER JOIN ancestors a ON d.id = a.parent_id
    )
    SELECT * FROM ancestors
    ORDER BY level DESC;  -- Order from top to bottom
END;
$$;


