CREATE FUNCTION users.get_depart_children(depart_id integer) RETURNS TABLE(id integer, depart_code character varying, depart_name character varying, depart_type_id integer, depart_type_name character varying, depart_type_level integer, parent_id integer, level integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH RECURSIVE children AS (
        -- Base case: Direct children
        SELECT 
            d.id,
            d.depart_code,
            d.depart_name,
            d.depart_type_id,
