        INNER JOIN users.tb_depart_types dt ON dt.id = d.depart_type_id
        WHERE d.parent_id = depart_id
        
        UNION ALL
        
        -- Recursive case: Get children of children
        SELECT 
            d.id,
            d.depart_code,
            d.depart_name,
            d.depart_type_id,
            dt.depart_type_name,
            dt.depart_type_level,
            d.parent_id,
            c.level + 1
        FROM users.tb_departs d
        INNER JOIN users.tb_depart_types dt ON dt.id = d.depart_type_id
        INNER JOIN children c ON d.parent_id = c.id
    )
    SELECT * FROM children
    ORDER BY level, depart_type_level, depart_code;
END;
