-- Name: get_depart_hierarchy(integer); Type: FUNCTION; Schema: users; Owner: postgres
--

CREATE FUNCTION users.get_depart_hierarchy(depart_id integer) RETURNS TABLE(id integer, depart_code character varying, depart_name character varying, depart_type_id integer, depart_type_name character varying, depart_type_level integer, parent_id integer, level integer, path integer[], full_path text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH RECURSIVE hierarchy AS (
        -- Base case: Start from given department
        SELECT 
            d.id,
            d.depart_code,
            d.depart_name,
            d.depart_type_id,
            dt.depart_type_name,
            dt.depart_type_level,
            d.parent_id,
            1 as level,
            ARRAY[d.id] as path,
            d.depart_name::TEXT as full_path
        FROM users.tb_departs d
        INNER JOIN users.tb_depart_types dt ON dt.id = d.depart_type_id
        WHERE d.id = depart_id
        
        UNION ALL
        
        -- Recursive case: Get all children
        SELECT 
            d.id,
            d.depart_code,
            d.depart_name,
            d.depart_type_id,
            dt.depart_type_name,
            dt.depart_type_level,
            d.parent_id,
            h.level + 1,
            h.path || d.id,
            (h.full_path || ' > ' || d.depart_name)::TEXT
        FROM users.tb_departs d
        INNER JOIN users.tb_depart_types dt ON dt.id = d.depart_type_id
        INNER JOIN hierarchy h ON d.parent_id = h.id
    )
    SELECT * FROM hierarchy
    ORDER BY level, depart_type_level, depart_code;
END;
$$;


