--
-- TOC entry 586 (class 1259 OID 25704)
-- Name: v_areas; Type: VIEW; Schema: users; Owner: postgres
--

CREATE VIEW users.v_areas AS
 SELECT d.id,
    d.depart_code AS area_code,
    d.depart_name AS area_name,
    d_hq.id AS head_office_id,
    d.depart_type_id,
    d.parent_id,
    d.is_active,
    d.created_at,
    d.updated_at
   FROM ((users.tb_departs d
     JOIN users.tb_depart_types dt ON ((dt.id = d.depart_type_id)))
     LEFT JOIN users.tb_departs d_hq ON (((d_hq.id = d.parent_id) AND (d_hq.depart_type_id = ( SELECT tb_depart_types.id
           FROM users.tb_depart_types
          WHERE ((tb_depart_types.depart_type_name)::text = 'hq'::text))))))
  WHERE ((dt.depart_type_name)::text = 'area'::text);


ALTER VIEW users.v_areas OWNER TO postgres;

