--
-- TOC entry 589 (class 1259 OID 25719)
-- Name: v_depart_hierarchy; Type: VIEW; Schema: users; Owner: postgres
--

CREATE VIEW users.v_depart_hierarchy AS
 WITH RECURSIVE hierarchy AS (
         SELECT d.id,
            d.depart_code,
            d.depart_name,
            d.depart_type_id,
            dt.depart_type_name,
            dt.depart_type_level,
            d.parent_id,
            1 AS level,
            ARRAY[d.id] AS path,
            (d.depart_name)::text AS full_path
           FROM (users.tb_departs d
             JOIN users.tb_depart_types dt ON ((dt.id = d.depart_type_id)))
          WHERE (d.parent_id IS NULL)
        UNION ALL
         SELECT d.id,
            d.depart_code,
            d.depart_name,
            d.depart_type_id,
            dt.depart_type_name,
            dt.depart_type_level,
            d.parent_id,
            (h.level + 1),
            (h.path || d.id),
            ((h.full_path || ' > '::text) || (d.depart_name)::text) AS text
           FROM ((users.tb_departs d
             JOIN users.tb_depart_types dt ON ((dt.id = d.depart_type_id)))
             JOIN hierarchy h ON ((d.parent_id = h.id)))
        )
 SELECT id,
    depart_code,
    depart_name,
    depart_type_id,
    depart_type_name,
    depart_type_level,
    parent_id,
    level,
    path,
    full_path
   FROM hierarchy;


ALTER VIEW users.v_depart_hierarchy OWNER TO postgres;

